    isTypeableCombobox(domReference) && ignoreInitialFocus,
  );

  const initialFocusRef = {
    get current() {
      return initialFocus;
    },
  };
  const returnFocusRef = {
    get current() {
      return returnFocus;
    },
  };
  const openInteractionTypeRef = {
    get current() {
      return openInteractionType;
    },
  };
  const openRef = {
    get current() {
      return open;
    },
